// Helpers the tests use to read a page the way a browser would. You do not edit this file.
// Call setViewport(width) to choose the browser width in px that @media (min-width / max-width) rules are checked against.
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

export function loadPage(dir, file) {
	const page = new DOMParser().parseFromString(readFileSync(join(dir, file), 'utf8'), 'text/html');
	document.documentElement.lang = page.documentElement.lang;
	document.head.innerHTML = page.head.innerHTML;
	document.body.innerHTML = page.body.innerHTML;
	for (const link of [...document.querySelectorAll('link[rel="stylesheet"]')]) {
		const style = document.createElement('style');
		style.textContent = readFileSync(join(dir, link.getAttribute('href')), 'utf8');
		link.replaceWith(style);
	}
	return page;
}

const INHERITED = new Set(['color', 'font-family', 'font-size', 'font-weight', 'line-height', 'text-align']);

function specificity(selector) {
	const ids = (selector.match(/#[\w-]+/g) ?? []).length;
	const classes = (selector.match(/\.[\w-]+|\[[^\]]*\]|:(?!:)[\w-]+/g) ?? []).length;
	const bare = selector.replace(/#[\w-]+|\.[\w-]+|\[[^\]]*\]|::?[\w-]+(\([^)]*\))?/g, ' ');
	const types = (bare.match(/[a-zA-Z][\w-]*/g) ?? []).length;
	return ids * 10000 + classes * 100 + types;
}

const beats = (a, b) => {
	for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return a[i] > b[i];
	return false;
};

let viewport = 1280;
export const setViewport = (width) => {
	viewport = width;
};

function mediaMatches(text) {
	const queries = text.split(/\s*,\s*/);
	return queries.some((query) => {
		if (/\b(print|speech)\b/.test(query) && !/\bscreen\b/.test(query)) return false;
		const features = [...query.matchAll(/\(\s*(min|max)-width\s*:\s*([\d.]+)(px|em|rem)\s*\)/g)];
		const known = (query.match(/\(/g) ?? []).length;
		if (features.length !== known) return false;
		return features.every(([, kind, number, unit]) => {
			const px = unit === 'px' ? Number(number) : Number(number) * 16;
			return kind === 'min' ? viewport >= px : viewport <= px;
		});
	});
}

function* styleRules(rules) {
	for (const rule of rules) {
		if (rule.selectorText !== undefined) yield rule;
		else if (rule.media && mediaMatches(rule.media.mediaText)) yield* styleRules(rule.cssRules);
	}
}

function declaredHere(element, property) {
	let best = null;
	let order = 0;
	for (const sheet of document.styleSheets) {
		for (const rule of styleRules(sheet.cssRules)) {
			order++;
			const value = rule.style.getPropertyValue(property);
			if (!value) continue;
			for (const part of rule.selectorText.split(',')) {
				const selector = part.trim();
				let matches = false;
				try {
					matches = !selector.includes('::') && element.matches(selector);
				} catch {}
				if (!matches) continue;
				const important = rule.style.getPropertyPriority(property) === 'important' ? 1 : 0;
				const rank = [important, specificity(selector), order];
				if (!best || beats(rank, best.rank)) best = { value, rank };
			}
		}
	}
	return best?.value ?? null;
}

// The value a rule in the stylesheet gives this element for a property, or null.
// Custom properties are resolved through var(). Inherited properties walk up the tree.
export function declared(element, property) {
	for (let node = element; node; node = INHERITED.has(property) ? node.parentElement : null) {
		const value = declaredHere(node, property);
		if (value !== null) return resolveVars(value);
	}
	return null;
}

export function resolveVars(value) {
	return value.replace(/var\(\s*(--[\w-]+)\s*(?:,\s*([^)]*))?\)/g, (_, name, fallback) => {
		const found = declaredHere(document.documentElement, name);
		return resolveVars((found ?? fallback ?? '').trim());
	});
}

export function toPx(value) {
	const match = /^(-?[\d.]+)(px|rem|em|ch|%)?$/.exec((value ?? '').trim());
	if (!match) return null;
	const number = Number(match[1]);
	const unit = match[2];
	if (unit === 'rem' || unit === 'em') return number * 16;
	if (unit === 'ch') return number * 8;
	if (unit === '%') return (number / 100) * 16;
	return number;
}

const NAMED = { white: [255, 255, 255], black: [0, 0, 0] };

export function toRgb(color) {
	const probe = document.createElement('span');
	probe.style.color = (color ?? '').trim();
	const text = NAMED[probe.style.color] ? `rgb(${NAMED[probe.style.color].join(',')})` : probe.style.color;
	const match = /^rgba?\((\d+),\s*(\d+),\s*(\d+)/.exec(text);
	return match ? [Number(match[1]), Number(match[2]), Number(match[3])] : null;
}

export const sameColor = (a, b) => {
	const [x, y] = [toRgb(a), toRgb(b)];
	return x !== null && y !== null && x.every((n, i) => n === y[i]);
};

const luminance = (rgb) => {
	const [r, g, b] = rgb.map((n) => {
		const c = n / 255;
		return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
	});
	return 0.2126 * r + 0.7152 * g + 0.0722 * b;
};

export function contrast(foreground, background) {
	const [a, b] = [toRgb(foreground), toRgb(background)];
	if (!a || !b) return 0;
	const [light, dark] = [luminance(a), luminance(b)].sort((x, y) => y - x);
	return (light + 0.05) / (dark + 0.05);
}

// Number of tracks in a grid-template-columns value, such as "repeat(3, 1fr)" or "14rem 1fr".
export function trackCount(value) {
	if (!value || value === 'none') return 0;
	let text = value.trim();
	let count = 0;
	const repeat = /repeat\(\s*(\d+)\s*,\s*((?:[^()]|\([^()]*\))*)\)/g;
	text = text.replace(repeat, (_, times, inner) => {
		count += Number(times) * trackCount(inner);
		return ' ';
	});
	const rest = text.replace(/minmax\([^()]*\)|fit-content\([^()]*\)|\[[^\]]*\]/g, (m) => (m.startsWith('[') ? ' ' : 'T'));
	return count + rest.split(/\s+/).filter(Boolean).length;
}

// The grid-template-areas value as rows of area names: [["header", "header"], ["side", "main"]].
export function areaRows(value) {
	return [...(value ?? '').matchAll(/"([^"]*)"|'([^']*)'/g)].map((m) => (m[1] ?? m[2]).trim().split(/\s+/));
}
